WITH history AS (SELECT DATE_TRUNC('DAY', "EVENT_DATE") AS period, EXTRACT(DOW FROM "EVENT_DATE") AS dow, COUNT(*) AS cnt FROM "FAKE_PROJECT"."DATASET"."ORDERS" WHERE "EVENT_DATE" >= '2026-05-01'::DATE - INTERVAL '28 DAY' AND "EVENT_DATE" < '2026-05-01'::DATE GROUP BY period, dow), medians AS (SELECT dow, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cnt) AS median FROM history GROUP BY dow), mads AS (SELECT history.dow AS dow, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ABS(history.cnt - medians.median)) AS mad FROM history JOIN medians ON history.dow = medians.dow GROUP BY history.dow), counts AS (SELECT dow, COUNT(*) AS n FROM history GROUP BY dow) SELECT medians.dow AS dow, medians.median AS median, mads.mad AS mad, counts.n AS n FROM medians JOIN mads ON medians.dow = mads.dow JOIN counts ON medians.dow = counts.dow